insert into audit_backup.rewrites_20261122_proposals (locale, slug, field, col, path, decision, old_text, new_text)
values
  ('en', 'parco-naturale-regionale-del-vulture', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Vulture Regional Natural Park is a protected natural area established in November [dated source]. This regional park includes the Vulture area as well as part of the municipal territories of Atella, Barile, Ginestra, Melfi, Rapolla, Rionero in Vulture, Ripacandida, Ruvo del Monte and San Fele, all belonging to the Province of Potenza.', 'The Vulture Regional Natural Park is a protected natural area that includes the Vulture area and parts of the municipalities of Atella, Barile, Ginestra, Melfi, Rapolla, Rionero in Vulture, Ripacandida, Ruvo del Monte and San Fele, all in the Province of Potenza.'),
  ('en', 'parco-naturale-regionale-terra-delle-gravine', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Terra delle Gravine natural park is a protected natural area established in Puglia in [dated source]. The area covers the provinces of Brindisi and Taranto, in the Murge area.', 'The Terra delle Gravine natural park is a protected natural area in Apulia, covering parts of the provinces of Brindisi and Taranto in the Murge area.'),
  ('en', 'ponga-nature-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Natural Park of Ponta is a Spanish protected natural space, situated in the central area of the Cantábrica range with a protected area of 20533 ha, and most of them are the town council of Ponta. It was intended to be first included in the Reds Park at the end of the period and its name as a natural park was later and with its own identity. It was declared by law 4 / [dated source].', 'Ponga Natural Park is a Spanish protected natural space in the central area of the Cantábrica range, with a protected area of 20,533 ha, most of it in the municipality of Ponga.'),
  ('en', 'reinheimen-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Reinheimen National Park is a national park in Norway that was established in [dated source]. The park consists of a 1,969-square-kilometre continuous protected mountain area. It is located in Møre og Romsdal and Innlandet counties in Norway. The park includes parts of the municipalities of Lesja, Skjåk, Vågå, Lom, Fjord, and Rauma. The park consists of much of the Tafjordfjella mountain range as well as the reindeer habitat in the northern part of the Ottadalen valley.', 'Reinheimen National Park is a national park in Norway with a continuous protected mountain area of 1,969 square kilometres in Møre og Romsdal and Innlandet counties. It includes parts of the municipalities of Lesja, Skjåk, Vågå, Lom, Fjord and Rauma, much of the Tafjordfjella mountain range and the reindeer habitat in the northern part of the Ottadalen valley.'),
  ('en', 'reynisdrangar', 'seo_description', 'seo_description', null, 'REWRITE', 'In [dated source] Reynisfjara [ˈreiːnɪsˌfjaːra] was rated the sixth best beach in the world.', 'Basalt sea stacks below Reynisfjall near Vík í Mýrdal in southern Iceland, framed by a black sand beach.'),
  ('en', 'reynisdrangar', 'tagline', 'tagline', null, 'REWRITE', 'In [dated source] Reynisfjara [ˈreiːnɪsˌfjaːra] was rated the sixth best beach in the world.', 'Basalt sea stacks below Reynisfjall near Vík í Mýrdal in southern Iceland, framed by a black sand beach.'),
  ('en', 'reynisfjara', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Reynisfjara is a popular black sand beach in southern Iceland near the town of Vík í Mýrdal. It is part of the Katla UNESCO Global Geopark on privately owned land. In February [dated source], following weeks of strong waves and easterly winds, part of the iconic basalt columns collapsed along with significant erosion of the beach. With the return of westerly winds in March, Reynisfjara is expected to return to its familiar appearance.', 'Reynisfjara is a popular black sand beach in southern Iceland near the town of Vík í Mýrdal. It is part of the Katla UNESCO Global Geopark, on privately owned land.'),
  ('en', 'rhine-falls', 'seo_description', 'seo_description', null, 'REWRITE', '13 November [dated source] to 3 January [dated source]: The illumination of the Schloss Laufen on the Rhine Fa', 'Europe''s largest waterfall, flanked by Laufen and Wörth castles and seen from the SBB railway bridge.'),
  ('en', 'rhine-falls', 'tagline', 'tagline', null, 'REWRITE', '13 November [dated source] to 3 January [dated source]: The illumination of the Schloss Laufen on the Rhine Fa', 'Europe''s largest waterfall, flanked by Laufen and Wörth castles and seen from the SBB railway bridge.'),
  ('en', 'rohkunborri-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Rohkunborri National Park is a national park in Troms county, Norway, that was established in [dated source]. The park consists of a 571-square-kilometre protected area, and is located in Bardu Municipality along the border with Sweden, about 30 kilometres southeast of the village of Setermoen and about 50 kilometres northeast of the town of Narvik.', 'Rohkunborri National Park is a national park in Troms county, Norway, with a protected area of 571 square kilometres. It lies in Bardu Municipality along the border with Sweden, about 30 kilometres southeast of the village of Setermoen and about 50 kilometres northeast of the town of Narvik.'),
  ('en', 'rosalia-kogelberg-nature-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'As part of the project “Barrier-free nature experience Rosalia-Kogelberg”, a hiking and nature experience for all senses was created between [dated source] and [dated source]. The project included, among other things, the conception and construction of a total of eleven barrier-free experience and rest stations along the so-called Eulenweg or along the “Tour Teichwiesen”.', 'As part of the project ''Barrier-free nature experience Rosalia-Kogelberg'', a hiking and nature trail for all the senses was created. The project included the design and construction of eleven barrier-free experience and rest stations along the Eulenweg and the Tour Teichwiesen.'),
  ('en', 'saimaa-unesco-global-geopark', 'seo_description', 'seo_description', null, 'REWRITE', 'The area received UNESCO Global Geopark status in [dated source].', 'A UNESCO Global Geopark with 65 geo-sites around Lake Saimaa, Finland''s largest lake.'),
  ('en', 'saimaa-unesco-global-geopark', 'tagline', 'tagline', null, 'REWRITE', 'The area received UNESCO Global Geopark status in [dated source].', 'A UNESCO Global Geopark with 65 geo-sites around Lake Saimaa, Finland''s largest lake.'),
  ('en', 'sainte-baume-regional-nature-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Sainte-Baume Regional Nature Park is a regional nature park created by decree on December 20, [dated source], with a perimeter of approximately 84,367 ha distributed between the two departments of Bouches-du-Rhône and Var, around the massif of the same name. It is the 52nd French Regional Natural Park.', 'The Sainte-Baume Regional Nature Park covers about 84,367 ha across the Bouches-du-Rhône and Var departments, around the massif of the same name. It is the 52nd French regional natural park.'),
  ('en', 'salpausselka-unesco-global-geopark', 'seo_description', 'seo_description', null, 'REWRITE', 'Salpausselkä Geopark was accepted on 13 April [dated source].', 'Salpausselkä Geopark spans Lahti, Hollola, Asikkala, Heinola, Sysma and Padasjoki in Finland.'),
  ('en', 'salpausselka-unesco-global-geopark', 'tagline', 'tagline', null, 'REWRITE', 'Salpausselkä Geopark was accepted on 13 April [dated source].', 'Salpausselkä Geopark spans Lahti, Hollola, Asikkala, Heinola, Sysma and Padasjoki in Finland.'),
  ('en', 'salpausselka-unesco-global-geopark', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Salpausselkä Geopark was accepted on 13 April [dated source]. Salpausselkä Geopark consists of the municipalities of Lahti, Hollola, Asikkala, Heinola, Sysma and Padasjoki. The area is located for example in Päijänte National Park, the Tiirismaa region, Kelvenne, Pulkkilanharju, Paistjarvi Reserve, Vakumuori, Water Division Nature Park, Koreakoivu and Kutajärvi.', 'Salpausselkä Geopark consists of the municipalities of Lahti, Hollola, Asikkala, Heinola, Sysma and Padasjoki. Its sites include Päijänte National Park, the Tiirismaa area, Kelvenne, Pulkkilanharju, the Paistjärvi reserve, Vakumuori, the Water Division Nature Park, Koreakoivu and Kutajärvi.'),
  ('en', 'salzburger-lungau-and-karntner-nockberge-biosphere', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Salzburger Lungau and the adjacent Carinthian Nockberge were awarded as a Biosphere Park by UNESCO in July [dated source]. It covers the entire Salzburg district of Tamsweg (Lungau) and adjacent areas of the Nockberge in Carinthia. This makes the area bordering the federal states of Salzburg and Carinthia a “model region for sustainable development”.', 'Salzburger Lungau and the adjacent Carinthian Nockberge have been recognised by UNESCO as a Biosphere Park. It covers the whole Salzburg district of Tamsweg (Lungau) and neighbouring parts of the Nockberge in Carinthia, making this border area of Salzburg and Carinthia a ''model region for sustainable development''.'),
  ('en', 'sequoia-park-of-monte-cabezon', 'seo_description', 'seo_description', null, 'REWRITE', 'The following are a "protected natural space" of Cantabria, declared a Natural Monument by Decree 41 / [dated ', 'The Sequoia Park of Monte Cabezón is a Natural Monument and protected natural space of Cantabria.'),
  ('en', 'sequoia-park-of-monte-cabezon', 'tagline', 'tagline', null, 'REWRITE', 'The following are a "protected natural space" of Cantabria, declared a Natural Monument by Decree 41 / [dated ', 'The Sequoia Park of Monte Cabezón is a Natural Monument and protected natural space of Cantabria.'),
  ('en', 'sequoia-park-of-monte-cabezon', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The following are a "protected natural space" of Cantabria, declared a Natural Monument by Decree 41 / [dated source] of the Government of Cantabria and included in the Network of Natural Space Protected by Cantabria Act 4 / [dated source] of 19 May.)', 'The Sequoia Park of Monte Cabezón is a protected natural space of Cantabria, declared a Natural Monument by the Government of Cantabria and included in Cantabria''s network of protected natural spaces.'),
  ('en', 'serra-da-encina-da-lastra-natural-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Sierra de la Lasse Natural Park () () () () is a Spanish protected natural space situated in the north-eastern province of Orense, in the municipality of Rubiana, Valdeoras, and was declared a Natural Park in [dated source] by the Galicia Board. It has an area of 3151.67 ha and an average height of 684 m. It''s a limestone valley with pronounced slopes and cantils with a Mediterranean forest. A particularly important area of public interest, especially for its rapist bird populations, among them the presence of the Royal Eagle and the Pereer Falcon. The abundance of caves - referred to here as shovels - leads to the existence of numerous colonies of bats, the most important of Galicia. A further point of interest lies in the presence of Mediterranean-type grazing areas characteristic of rocky mountain areas.)', 'Serra da Enciña da Lastra Natural Park is a Spanish protected natural space in the north-east of the province of Ourense, in the municipality of Rubiá (Valdeoras), declared a Natural Park by the Galician government. It covers 3,151.67 ha with an average altitude of 684 m: a limestone valley with steep slopes, cliffs and Mediterranean woodland. It is especially important for birds of prey, including the golden eagle and the peregrine falcon. Its many caves shelter numerous bat colonies, the most important in Galicia, and it also has Mediterranean-type grazing land typical of rocky mountain areas.'),
  ('en', 'serra-de-tramuntana', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Serra de Tramuntana (Balearic Catalan: [ˈsɛrə ðə tɾəmunˈtanə]) is a mountain range running southwest–northeast which forms the northern backbone of the Spanish island of Mallorca. It is also the name given to the comarca of the same area. On 27 June [dated source], the Tramuntana Range was awarded World Heritage Status by UNESCO as an area of great physical and cultural significance.', 'The Serra de Tramuntana is a mountain range running southwest–northeast that forms the northern backbone of the Spanish island of Mallorca; it is also the name of the comarca covering the same area. The Tramuntana Range has UNESCO World Heritage status, recognised as an area of great physical and cultural significance.'),
  ('en', 'sheskinmore-nature-reserve', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sheskinmore Nature Reserve Location: GPS: Latitude: 54.794006 Longitude: -8.463635 Area : Sheskinmore refers to a large area of sand dunes, lake and marsh that lies between Kiltooris and Ballinreavy Strand, north west of Ardara, Co. Donegal. The area is designated as a Special Area of Conservation, a Special Protection Area and a Wildfowl Sanctuary. The area is easily accessed from the gate at Mullyvea opposite Kiltooris Lough. Is ceantar mór dumcha, locha agus seascainn é Seascann Mór atá idir Cill Dorais agus Trá Bhaile an Riabhaigh ar thaobh thiar thuaidh d’Ard Ratha, Co. Dhún na nGall. Tá an ceantar ainmnithe mar Cheantar Speisialta Caomhnaithe, mar Cheantar Cosanta Speisialta agus mar Thearmann Éanlaithe. Tá sé furasta dul isteach ann tríd an geata ag Mullach Bheitheach os coinne Loch Chill Dorais. Habitats The area is mostly a fixed sand dune system, which includes machair grassland, dune slacks, Sheskinmore lough and the surrounding marsh, fen and reedbed. There is some oak and hazel scrub with heath on the drier northern slopes behind the lough and there is also coastal heath on the Carrickalagh headland. Sescenn Mór literally means “big marsh” and the marshy plain contains much of the areas’ interesting flora and fauna. South and west of the flat marshy plain there are sandy machair grasslands which evolve into high undulating sand dunes along Trawmore Strand and Ballinreavy Strand. Gnáthóga Is córas duimhche seasta an ceantar seo den chuid is mó ina bhfuil talamh féarach, machaire, dumhcha, Loch an tSeascainn Mhóir, machaire moing agus sraith ghiolcach thart air. Tá crainn dharach agus scrobarnach coil maraoin le fraoch ar na fánaí tirime ar an taobh thuaidh den loch agus tá fraoch cósta ar cheann tire Charraig Adhlactha. Ciallaíonn Seascann Mór bogach nó corrach mór agus ta fásra agus ainmhíthe suimiúla le fail ar chuid mhaith den mhachaire corrach seo. Ar an taobh theas agus thiar den mhachaire tá talaimh féir gainimh a éiríonn ansin i ndumhcha droimnigh arda le taobh trá na Trá Móire agus Trá Bhaile an Riabhaigh Birds A visit at any time of year is always interesting for birdlife. During the winter a small flock of Greensland White Fronted Geese feed undisturbed here. Chough and Twite also feed here in Winter. Brent Goose, Whooper Swan, Wigeon, Tufted Duck, Goldeneye and Golden Plover are other winter visitors. Lapwing, Mallard, Teal, Snipe and Mute Swan are found all year round as are Linnet, Skylark, Meadow pipit, Stonechat and Reed Bunting. Summer visitors include the Grasshopper, Sedge and Willow Warblers and Wheatear, Swallow and Cuckoo. Birds of prey species use this vast open undisturbed site to hunt. Ein Is fiú go mór cuairt a thabhairt anseo ag am ar bith den bhliain chun an éanlaith shuimiúil a fheiceáil. I rith an gheimhridgh bíonn scata Géanna le Brollaigh Bhána ón Ghraonlainn a chothú ann. Bionn an Cág Deargchosach agus an Ghleoiseach Shléibhe ann as gheimhreadh. Is cuairteoirí geimhridgh eile iad an Ghé Dhubh, an Eala Ghlórach, an Lacha rua, an Lacha Dhubh, an Feadóg Shléibhe agus Feadóg na Súile Óire. Chítear an Pilibín, an Mallard, an Phraslacha, an Naoscach, an Eala Bhalbh ann I rith nab liana chomh maith leis an Ghleoiseach, an Fhuiseog, an Riabhógmhóna, an Chloch Dearg agus an Ghealóg Dhúcheannach. I rith an tsamhraidh bionn an Dreoilin Teaspaigh, an Chíb, an Ceolaire Sailí, an Chlochrán, an Fhainleog agus an Chuach le feiceáil ann. Úsáideann éin chreiche an láithreán leathan oscaillte seo mar thalamh seilge. Plants The fixed dune and machair are managed to enhance their species richness. Cattle graze extensively during the winter months only. Orchid species include the Marsh Helleborine, Bee Orchid, Frog Orchid and the rare Irish Orchid. There is a succession of colour throughout the summer months in the dunes and on the marsh, from yellows and whites in spring through to the pinks and purples of the late summer. Rarieties recorded in the area include the aquatic slender naiad and pipewort, the tiny petalwort, also quillwort, hoary whitlow grass and many stonewort species. Plandaí Riaraítear na dumhcha seasta agus an machaire chun siabhreas na ngnéithe a mhéadu. Bíonn eallach ag iníorgo tréan anseo i rith míonna an gheimhridh amháin. I measc an ngnéithe magairlíne tá Cuacihín Corraigh, Magairlín na mBeach, Magairlín an Ioscáin agus Magairlín Éireannach atá neamhchoitianta. Bíonn athraithe datha trí mhíonna an t-samhraidh sna dumhcha agus ar an machaire ó dhath buí agus bán an earraigh go dathanna bándearga agus corcra dheireadh an t-samhraidh. I measc na ngnéithe neamhchoitianta a rinneadh cuntas orthu sa cheantar seo tá nimfigh uisce, píbín uisce, tursarraing chleite, bosán anagair agus tursarraing chloiche. Animals Rabbits, badgers and foxes are the most common mammals recorded at Sheskinmore. Otter have been seen in the lough. Frog and newt breed in and around the dune slacks and the common lizard breeds on the drier slopes. The protected tiny marsh snail species Vertigo geyeri is found in the fen habitat west of the lough. The area is also noteworthy for the variety of butterflies and dragonflies that breed here. Marsh fritillary and dingy skipper both breed at Sheskinmore along with 18 other butterfly species. Sheskinmore lough and associated wetlands is the most species rich site in Donegal for dragonflies and damselflies. Fifteen species have been recorded, the most interesting being the Black-tailed Skimmer and the small Blue tip. 2 Ainmhithe Is iad coiníní, broic agus sionnaigh na siní is coitianta ar an t-Seascann Mór. Chonacthas dobharchúnna sa loch. Bíonn an frog agus an t-earc luachra ag síolrú thart ar na dumhcha agus an t-earc coitianta ag síolrú ar na fánaí tirime. Faightear seilidí beaga corraigh. Vertigo geyeri atá cosanta sa ghnáthóg moinge taobh thiar den loch.Tá cáil ar an cheantar seo as ucht ilghnéitheachta na bhfeileacán agus na snatháidí móra a shíolraíonn anseo. Bíonn Fritileáin corraigh agus Preabairí modartha ag síolrú ar an SEascann Mór maraon le ocht ngné déag d’fheileacán. Bíonn níos mó gnéithe de shnatháidí móra agus cuileoga daimsil le fail I gceantar Loch an t-Seascainn Mhóir agus na talaimh fliucha thart air ná in áit ar bith eile i gCo. Dhún na nGall. Rinneadh cuntas oifigiúil ar cúig ghné déag díobh agus Snatháid an Eireaball Dhuibh agus Snatháid Bheag an Bhairr Ghoirm ar na cinn is suimiúla. Management The property is managed by NPWS to maximise its biodiversity. The area is rich in marsh and dune plants and supports a wide variety of invertebrates and birds. The cereal plot at the Mullyvea entrance was first planted in [dated source] to feed finches and buntings during the winter months. Another plot is planned for Sandfield. The site is winter grazed to encourage floral diversity and cow pats are also a source of food for foraging chough. Stocking rates are periodically reviewed and horses may at times be grazed on the site. Various methods have been tried to control bracken. A sluice is in place to control water levels at the lough in order to protect the slender naiad population. In [dated source] McGlinchey’s house at Sandfield was fully restored and is now used as a field studies centre. Bainistíocht Riaraíonn an NPWS an eastát se chun uasmhéid éagsúlacht bheatha a fháil. Is ceantar saibhir é le plandaí seascainn agus dumhcha a chothaíonn éagsúlacht leathan éan agus ainmhíthe gan cnámh droma. Cuireadh arbhar don chéad uair I [dated source] ag bealach insteach ag Mullach Bheitheach chun na gealóga a bheathú i rith an gheimhridh.Tá plean do phlota eile arbhair ag Achadh an Ghainimh. Cuirtear eallach ag iníor ar an láitrhreán sa gheimhreadh chun cuidiú leis an éagsúlacht bláthanna agus is foinse bia an cac bó do na cáig dhearg-chosacha. Coinnítear súil ar an stoc ó am go ham agus b’fheider go ligtar do chapaill a bheith ar fhéar anseo chomh maith. Úsáideadh dóigheanna éagsúla chun smacht a chur ar an raithneach. Cuireadh loc-chomhla ann chun leibhéil an uisce a chosaint. I [dated source] coíríodh Teach Mhic Loinsigh in Achadh an Ghainimh agus tá sé in úsáid mar ionad staidéir amuigh faoin aer. Access & Safety There are three signed access points. The main entrance is at the Mullyvea gate opposite Kiltooris Lough. There is access from the east side at both Murveagh and Sandfield of the R261. Walkers should be cautious of grazing animals between October and May and dogs should be kept on a lead and under control at all times. Some of the land within the site is still privately owned so be careful to close gates and not to damage walls or fences. Appropriate walking clothing and a map and compass are recommended. Any damaging activities should be reported to NPWS at Gleanveagh National Park 074 -9137090 or NPWS at Ballinafad, Co. Sligo, 071 9666700 Bealach Isteach agus Sábháilteacht Tá trí bhealach isteach le comharthaí. Tá an príomhbhealach isteach ag geata an Mhullaigh Bheitheach os coinne Loch Chill Dorais. Tá bealach isteach ón taobh thoir ag Muirbheitheach Bheitheach agus Achadh an Ghainimh ón R261. Ba choir do shiúlóirí o bheith cúramach roimh ainmhíthe ar fhéar ó Dheireadh Fómhair go Bealtaine agus ba cheart madaí a choinneáil ar éill agus faoi smacht an t-am uilig. Ná dean dearmad na geataí a dhruid ná dochar a dhéanamh do bhallaí agus do fhálta.Moltar do shiúlóirí éadai foirstineacha a chaítheamh agus léarscáil agus compass a thabhairt leo. Má bhíonn imeachtaí a chuisíonn dochar ba choir fios a chur ar an tSeirbhís Páirceanna Náisiúnta agus Fiadhúlra I nGleann Bheitheach 074-9137090 nó ag Baile an Atha Fada, Co. Shligigh 071- 9666700 Established: Ownership: State-owned', 'Sheskinmore is a large area of sand dunes, lake and marsh between Kiltooris and Ballinreavy Strand, north-west of Ardara, Co. Donegal. It is a Special Area of Conservation, a Special Protection Area and a Wildfowl Sanctuary, and is easily reached from the gate at Mullyvea opposite Kiltooris Lough. The site is mostly a fixed dune system with machair grassland, dune slacks, Sheskinmore Lough and its surrounding marsh, fen and reedbed. In winter a small flock of white-fronted geese feeds here, along with chough and twite; orchids include the marsh helleborine, bee orchid and the rare Irish orchid. The reserve is managed by NPWS and grazed in winter to encourage floral diversity. Walkers should take care around grazing animals between October and May, keep dogs on a lead and close gates, as some of the land is privately owned.'),
  ('en', 'sila-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sila National Park (Italian: Parco nazionale della Sila) is an Italian national park in Calabria, located on the Sila Plateau. It was established in 1997 and covers about 74,000 hectares (180,000 acres). Its highest mountains are Mt. Botte Donato (1,928 m), in Sila Grande, and Mt. Gariglione (1,764 m) in Sila Piccola. The park was established with the Regional Decree of 14 November [dated source] and includes its own management agency. The park includes the territories formerly part of the Calabria National Park (1968), and protects areas of great environmental interest in Sila Piccola, Sila Grande and Sila Greca, for a total of 736.95 square kilometres (284.54 sq mi), in 21 municipalities (comuni) and 6 "mountain communities" (comunità montane) across the three Calabrian provinces of Catanzaro, Cosenza and Crotone.', 'Sila National Park (Italian: Parco nazionale della Sila) is an Italian national park in Calabria, on the Sila Plateau. It was established in 1997 and covers about 74,000 hectares. Its highest mountains are Mt. Botte Donato (1,928 m) in Sila Grande and Mt. Gariglione (1,764 m) in Sila Piccola. The park takes in land formerly part of the Calabria National Park (1968) and protects areas of great environmental interest in Sila Piccola, Sila Grande and Sila Greca, in 21 municipalities across the provinces of Catanzaro, Cosenza and Crotone.'),
  ('en', 'sjunkhatten-national-park', 'seo_description', 'seo_description', null, 'REWRITE', 'Sjunkhatten National Park was established in [dated source] in Nordland county, Norway.', 'A 417.5 km2 national park on a peninsula between Sørfolda and Saltfjorden in Nordland, Norway.'),
  ('en', 'sjunkhatten-national-park', 'tagline', 'tagline', null, 'REWRITE', 'Sjunkhatten National Park was established in [dated source] in Nordland county, Norway.', 'A 417.5 km2 national park on a peninsula between Sørfolda and Saltfjorden in Nordland, Norway.'),
  ('en', 'sjunkhatten-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Sjunkhatten National Park was established in [dated source] in Nordland county, Norway. The park consists of a 417.5-square-kilometre continuously protected area, including 39.8-square-kilometre sea area in Bodø Municipality, Fauske Municipality, and Sørfold Municipality. The park is located on a peninsula between the Sørfolda fjord and Saltfjorden, including glacier-formed landscape, caves and water systems, fjords, the large lake Heggmovatnet, rare animal species, and cultural heritage.', 'Sjunkhatten National Park lies in Nordland county, Norway. It is a continuous protected area of 417.5 square kilometres, including 39.8 square kilometres of sea, in Bodø, Fauske and Sørfold municipalities. The park sits on a peninsula between the Sørfolda fjord and Saltfjorden, with glacier-formed landscape, caves and water systems, fjords, the large lake Heggmovatnet, rare animal species and cultural heritage.'),
  ('en', 'south-harz-nature-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The South Harz Nature Park (German: Naturpark Südharz) is located in the county of Nordhausen in north Thuringia, Germany. The act designating this nature park in the Harz Mountains came into force on 31 December [dated source] and thus founded the fifth nature park in Thuringia. It has an area of 267 km². The park is managed by the South Harz Tourist Association (Südharzer Tourismusverband e.V.) in conjunction with the Kyffhäuser Nature Park.', 'The South Harz Nature Park (German: Naturpark Südharz) lies in the district of Nordhausen in northern Thuringia, Germany. It is the fifth nature park in Thuringia and covers 267 km² of the Harz Mountains. The park is managed by the South Harz Tourist Association (Südharzer Tourismusverband e.V.) together with the Kyffhäuser Nature Park.'),
  ('en', 'sparbach-nature-park', 'seo_description', 'seo_description', null, 'CLEAR', 'Während des Lockdown im April [dated source] wurde im Naturpark Sparbach eine Schwarzföhre „angepecht“. Dieses', ''),
  ('en', 'sparbach-nature-park', 'tagline', 'tagline', null, 'CLEAR', 'Während des Lockdown im April [dated source] wurde im Naturpark Sparbach eine Schwarzföhre „angepecht“. Dieses', ''),
  ('en', 'sparbach-nature-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'CLEAR', 'Während des Lockdown im April [dated source] wurde im Naturpark Sparbach eine Schwarzföhre „angepecht“. Dieses Ereignis wurde in einem Film festgehalten.', ''),
  ('en', 'sternberg-lake-land-nature-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Sternberger Lakeland Nature Park is a development area for agriculture and tourism (Landesraumentwicklungprogramm M-V [dated source]), not for industrial plants. The Expert Landscape Framework Plan (GLRP) identifies the entire area as a special area for the biotope network, which has a high to very high importance for the landscape.', 'The Sternberg Lake Land Nature Park is designated for agricultural and tourism development, not for industrial plants. The expert landscape framework plan (GLRP) classes the entire area as a special area for the biotope network, of high to very high importance for the landscape.'),
  ('en', 'tomorr-mountain-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Tomorr Mountain National Park is a national park founded in 1956 that lies in southern Albania, nestled in the central and higher portions of the Tomorr massif, spanning an area of 261.06 km2 since [dated source], and expanded to include its quarry areas since [dated source]. The park covers a territory of 26,106 ha . The area falls within the Berat County and only 1,278 ha inside the Elbasan County. The park was established in 1956 and is considered one of the most important protected areas for the maintenance of mountainous biodiversity and ecosystem integrity at the national level. The park has been recognised as an Important Plant Area of international importance by Plantlife.', 'Tomorr Mountain National Park, founded in 1956, lies in southern Albania in the central and higher parts of the Tomorr massif and covers 261.06 km2 (26,106 ha). Most of it is in Berat County, with only 1,278 ha in Elbasan County. It is considered one of the most important protected areas for mountain biodiversity and ecosystem integrity in Albania and is recognised by Plantlife as an Important Plant Area of international importance.'),
  ('en', 'tongariro-northern-circuit', 'seo_description', 'seo_description', null, 'REWRITE', 'Approximately 2,500 hikers completed the walk in the [dated source]/22 season.', 'A three- to four-day Great Walk through Tongariro National Park, circling Mount Ngauruhoe over about 50 km.'),
  ('en', 'tongariro-northern-circuit', 'tagline', 'tagline', null, 'REWRITE', 'Approximately 2,500 hikers completed the walk in the [dated source]/22 season.', 'A three- to four-day Great Walk through Tongariro National Park, circling Mount Ngauruhoe over about 50 km.'),
  ('en', 'una-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Una National Park was established on 29 May [dated source] around the rivers Upper Una River, Krka and the Unac. It is Bosnia and Herzegovina''s largest national park. The main purpose of the park is to protect the unspoiled Una river and its tributaries Krka and Unac, which run through it.', 'Una National Park lies around the Upper Una River and its tributaries the Krka and the Unac. It is the largest national park in Bosnia and Herzegovina, and its main purpose is to protect the unspoiled Una and these tributaries, which run through it.'),
  ('en', 'wienerwald-biosphere-reserve', 'seo_description', 'seo_description', null, 'REWRITE', 'The Wienerwald was designated as a Biosphere Reserve in [dated source] by UNESCO. This standing protects the g', 'The Wienerwald is a UNESCO Biosphere Reserve of wooded hills, meadows, orchards, vineyards and dry grasslands in Lower Austria and Vienna.'),
  ('en', 'wienerwald-biosphere-reserve', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Wienerwald was designated as a Biosphere Reserve in [dated source] by UNESCO. This standing protects the great variety of natural and cultural elements that make this region so unique and valuable. Wide range of wooded hills alternates with vast meadows, pastures and fruit orchards as well as vineyards and dry grasslands - the products from centuries of cultivation by humans. Four Nature Parks and the Viennese Lainzer Tiergarten, an extensive game park, are among the 15 nature preserves in this region.
